"""Snapping span boundaries to a fixed step, for payroll."""

import typing

import hourglass.errors
import hourglass.models
import hourglass.parsing


def check_step(step: int) -> None:
    """Raise ProjectError unless step is a positive number of minutes dividing an hour."""
    if step <= 0 or 60 % step != 0:
        raise hourglass.errors.ProjectError(
            f'step must be a positive number of minutes that divides an hour evenly, got {step}'
        )


def round_minutes(minutes: int, step: int) -> int:
    """Round to the nearest multiple of step, with halves going up."""
    return (minutes + step // 2) // step * step


def round_span(span: hourglass.models.Span, step: int) -> hourglass.models.Span:
    """Snap both ends of a span to the step. A span that collapses to nothing is an error."""
    check_step(step)
    start = round_minutes(span.start, step)
    end = round_minutes(span.end, step)
    if start >= end:
        raise hourglass.errors.ProjectError(
            f'{hourglass.parsing.format_span(span)} is too short to keep at a step of {step}'
        )
    return hourglass.models.Span(start, end)


def label_span(span: hourglass.models.Span) -> str:
    """Describe a span as 09:00-17:15 (8h 15m)."""
    hours, minutes = divmod(span.minutes, 60)
    return f'{hourglass.parsing.format_span(span)} ({hours}h {minutes}m)'


def rounded_labels(spans: typing.Iterable[hourglass.models.Span], step: int) -> typing.List[str]:
    """Round every span to the step and return one label per span, in order."""
    check_step(step)
    return [label_span(round_span(span, step)) for span in spans]
