import unittest

import hourglass.errors
import hourglass.models
import hourglass.parsing
import hourglass.rounding


def spans(*texts):
    return [hourglass.parsing.parse_span(text) for text in texts]


class RoundedLabelsTest(unittest.TestCase):
    def test_label_format(self):
        self.assertEqual(
            hourglass.rounding.rounded_labels(spans('09:00-17:15'), 15),
            ['09:00-17:15 (8h 15m)'],
        )

    def test_rounds_to_nearest(self):
        self.assertEqual(
            hourglass.rounding.rounded_labels(spans('08:52-17:07', '09:10-10:20'), 15),
            ['09:00-17:00 (8h 0m)', '09:15-10:15 (1h 0m)'],
        )

    def test_halves_round_up(self):
        self.assertEqual(
            hourglass.rounding.rounded_labels(spans('09:07-10:insert'.replace('insert', '22')), 15),
            ['09:00-10:15 (1h 15m)'],
        )
        self.assertEqual(
            hourglass.rounding.rounded_labels(spans('09:08-10:00'), 15),
            ['09:15-10:00 (0h 45m)'],
        )

    def test_end_of_day(self):
        self.assertEqual(
            hourglass.rounding.rounded_labels(spans('23:00-24:00'), 30),
            ['23:00-24:00 (1h 0m)'],
        )

    def test_empty_list(self):
        self.assertEqual(hourglass.rounding.rounded_labels([], 15), [])

    def test_bad_steps(self):
        for step in (0, -15, 7, 25, 90):
            with self.assertRaises(hourglass.errors.ProjectError):
                hourglass.rounding.rounded_labels(spans('09:00-10:00'), step)

    def test_bad_step_with_no_spans(self):
        with self.assertRaises(hourglass.errors.ProjectError):
            hourglass.rounding.rounded_labels([], 0)

    def test_span_collapsing_is_an_error(self):
        with self.assertRaises(hourglass.errors.ProjectError):
            hourglass.rounding.rounded_labels(spans('09:01-09:05'), 15)


if __name__ == '__main__':
    unittest.main()
